// plugins/withCloudKit.js
// Native config for CloudKit sync (patches 1 and 2 in dev_docs/CLOUDKIT_SYNC_PLAN.md). The ios/ folder is regenerated by
// `npm run ios:reset`, so this config lives here and never in the generated project.
//
// It does four things:
//   1. Adds the iCloud container and CloudKit entitlement, so the app may open its own zone, and the push entitlement
//      (aps-environment) that the change subscriptions need (patch 8b).
//   2. Sets CKSharingSupported and the remote-notification background mode, so a till can accept the share the owner sends
//      and hear about new records while it is not in front (the subscriptions are made by the CloudKit module, patch 8b).
//   3. Raises the iOS deployment target to 17, which CKSyncEngine needs. It sets both the Podfile platform and the Xcode
//      build setting, because the Podfile alone does not change the app target.
//   4. Raises any pod target that still asks for iOS older than 15 (some resource bundles declare 9.0 to 13.4), because Xcode 27 refuses
//      to build below 15.0 (0231). It goes inside the Podfile's own post_install block.
//   5. Adopts the UIScene lifecycle (0232). iOS 27 apps built with the iOS 27 SDK crash at launch without it. It adds the scene manifest, moves
//      React Native's window set-up out of the AppDelegate into a SceneDelegate, and hands URLs and CloudKit share links on from there.
//   6. Adds the AppDelegate method iOS calls when someone taps a CloudKit share link on this device
//      (`userDidAcceptCloudKitShareWith`). Expo forwards a fixed set of delegate calls and this is not one of them, so the
//      method has to be written into the generated AppDelegate. It only records the link and points at the CloudKit
//      module, which does the accepting (patch 2 of dev_docs/CLOUDKIT_SYNC_PLAN.md).
// The aps-environment entitlement was left out until the push subscriptions landed. They have (patch 8b), so it is set now. An app with it
// must be signed with a push-enabled provisioning profile: enable Push Notifications for the App ID in the Apple Developer account first, or
// the build fails to sign.
const { withEntitlementsPlist, withInfoPlist, withPodfileProperties, withPodfile, withXcodeProject, withAppDelegate } = require('@expo/config-plugins');

const CONTAINER = 'iCloud.com.aidens3dp.pos';
const DEPLOYMENT_TARGET = '17.0';

// The key the CloudKit module reads: a share link that opened the app, kept for a cold launch.
const PENDING_INVITE_KEY = 'cloudkitPendingInvite';
// The note the CloudKit module listens for, so a warm app joins the moment the link is tapped.
const SHARE_NOTIFICATION = 'cloudkitDidAcceptShare';
const SHARE_MARKER = '// CloudKit share links (added here by plugins/withCloudKit.js).';

// The entitlements, as a plain function so the node tests can check them. `aps-environment` (patch 8b) is what lets the app receive the
// silent pushes CloudKit sends when records change. It is set to `development`, and an archive signed with a push-enabled distribution
// profile is expected to carry `production` instead (check this on the first TestFlight build). An existing value is kept.
function applyEntitlements(entitlements) {
  entitlements['com.apple.developer.icloud-container-identifiers'] = [CONTAINER];
  entitlements['com.apple.developer.icloud-services'] = ['CloudKit'];
  if (!entitlements['aps-environment']) entitlements['aps-environment'] = 'development';
  return entitlements;
}

const withIcloudEntitlements = (config) =>
  withEntitlementsPlist(config, (c) => {
    c.modResults = applyEntitlements(c.modResults);
    return c;
  });

const withSharingSupport = (config) =>
  withInfoPlist(config, (c) => {
    c.modResults.CKSharingSupported = true;
    c.modResults.UIBackgroundModes = [...new Set([...(c.modResults.UIBackgroundModes ?? []), 'remote-notification'])];
    return c;
  });

const withPodfileTarget = (config) =>
  withPodfileProperties(config, (c) => {
    c.modResults['ios.deploymentTarget'] = DEPLOYMENT_TARGET;
    return c;
  });

const withProjectTarget = (config) =>
  withXcodeProject(config, (c) => {
    for (const entry of Object.values(c.modResults.pbxXCBuildConfigurationSection())) {
      const bs = entry && entry.buildSettings;
      if (bs && bs.IPHONEOS_DEPLOYMENT_TARGET !== undefined) bs.IPHONEOS_DEPLOYMENT_TARGET = DEPLOYMENT_TARGET;
    }
    return c;
  });

// iOS calls this when a share link is tapped on the device. It records the link (for a launch that has not loaded the
// CloudKit module yet) and hands the metadata to the module, which does the accepting. The method is added inside the
// AppDelegate class, and the marker keeps a second run of prebuild from adding it twice.
//
// This is a plain text transform on purpose: it takes the AppDelegate's text and gives the text back, so the node tests
// can check the result without a build. An Objective-C AppDelegate (not what this project generates) is left alone rather
// than having Swift written into it, and an AppDelegate that already carries the marker is returned unchanged.

/** The braces that hold a class body: the `{` after `marker` and the `}` that closes it. Null when either is missing. */
function classBody(contents, marker) {
  const start = contents.search(marker);
  if (start < 0) return null;
  const open = contents.indexOf('{', start);
  if (open < 0) return null;
  let depth = 0;
  for (let i = open; i < contents.length; i += 1) {
    if (contents[i] === '{') depth += 1;
    else if (contents[i] === '}') {
      depth -= 1;
      if (depth === 0) return { close: i };
    }
  }
  return null;
}

function injectShareLinkHandler(contents, language = 'swift') {
  if (language !== 'swift') return contents;
  if (contents.includes(SHARE_MARKER)) return contents;
  const withImport = /^\s*import CloudKit\s*$/m.test(contents)
    ? contents
    : contents.replace(/^(\s*import [^\n]+\n)/m, `$1import CloudKit\n`);
  // The generated AppDelegate.swift holds a second class (ReactNativeDelegate) after AppDelegate, so the file's last
  // brace is the wrong place: the method must go inside AppDelegate's own braces or iOS never calls it.
  const body = classBody(withImport, /class\s+AppDelegate\b/);
  if (!body) return contents;
  const handler = [
    '',
    `  ${SHARE_MARKER}`,
    '  // @objc is explicit on purpose: the runtime finds the method by selector, and the superclass does not declare it,',
    '  // so nothing else would expose it to UIKit.',
    '  @objc public func application(_ application: UIApplication, userDidAcceptCloudKitShareWith metadata: CKShare.Metadata) {',
    '    if let url = metadata.share.url?.absoluteString {',
    `      UserDefaults.standard.set(url, forKey: "${PENDING_INVITE_KEY}")`,
    '    }',
    `    NotificationCenter.default.post(name: Notification.Name("${SHARE_NOTIFICATION}"), object: metadata)`,
    '  }',
    '',
  ].join('\n');
  return withImport.slice(0, body.close) + handler + withImport.slice(body.close);
}

// 0231: Xcode 27 only builds for iOS 15.0 and up, and a few pods' resource bundles (RNDeviceInfo, RNCAsyncStorage, RNSVG) still say 9.0 to 13.4,
// which stops the build. This writes a small loop at the top of the Podfile's post_install block that lifts any pod target below 15.0 to ours.
const PODS_MARKER = '# Raise pod targets below iOS 15 (added here by plugins/withCloudKit.js).';
function injectPodsTarget(contents) {
  if (contents.includes(PODS_MARKER)) return contents;
  const hook = /^([ \t]*)post_install do \|installer\|[ \t]*\r?\n/m;
  const m = hook.exec(contents);
  if (!m) return contents;
  const pad = m[1] + '  ';
  const snippet = [
    `${pad}${PODS_MARKER}`,
    `${pad}installer.pods_project.targets.each do |t|`,
    `${pad}  t.build_configurations.each do |bc|`,
    `${pad}    v = bc.build_settings['IPHONEOS_DEPLOYMENT_TARGET']`,
    `${pad}    bc.build_settings['IPHONEOS_DEPLOYMENT_TARGET'] = '${DEPLOYMENT_TARGET}' if v && v.to_f < 15.0`,
    `${pad}  end`,
    `${pad}end`,
    '',
  ].join('\n');
  return contents.slice(0, m.index + m[0].length) + snippet + contents.slice(m.index + m[0].length);
}

const withPodsTarget = (config) =>
  withPodfile(config, (c) => {
    c.modResults.contents = injectPodsTarget(c.modResults.contents);
    return c;
  });

// 0232: the UIScene lifecycle. A build with the iOS 27 SDK stops at launch (UIApplicationEvaluateRuntimeIssueForNoSceneLifecycleAdoption)
// unless the app declares a scene and creates its window in a scene delegate. Expo SDK 54's generated AppDelegate makes the window itself,
// so this (1) declares the scene in Info.plist, (2) stops the AppDelegate starting React Native and keeps the launch options for the scene,
// and (3) appends a SceneDelegate to AppDelegate.swift that makes the window and starts React Native in it. URLs and universal links that
// iOS now delivers to the scene go back through the AppDelegate's own methods, so expo-linking still sees them. A CloudKit share link also
// arrives at the scene now (`userDidAcceptCloudKitShareWith` on the scene, or `cloudKitShareMetadata` on a cold launch).
// Written for the SDK 54 template. If its text is not found this throws, because a scene manifest without a SceneDelegate gives a black screen.
const SCENE_MARKER = '// Scene lifecycle (added here by plugins/withCloudKit.js).';

function applySceneManifest(plist) {
  plist.UIApplicationSceneManifest = {
    UIApplicationSupportsMultipleScenes: false,
    UISceneConfigurations: {
      UIWindowSceneSessionRoleApplication: [
        { UISceneConfigurationName: 'Default Configuration', UISceneDelegateClassName: '$(PRODUCT_MODULE_NAME).SceneDelegate' },
      ],
    },
  };
  return plist;
}

const SCENE_DELEGATE = [
  '',
  SCENE_MARKER,
  '// iOS 27 needs an app to use scenes. The window is made here, and React Native starts in it.',
  'class SceneDelegate: UIResponder, UIWindowSceneDelegate {',
  '  var window: UIWindow?',
  '',
  '  private var appDelegate: AppDelegate? { UIApplication.shared.delegate as? AppDelegate }',
  '',
  '  func scene(_ scene: UIScene, willConnectTo session: UISceneSession, options connectionOptions: UIScene.ConnectionOptions) {',
  '    guard let windowScene = scene as? UIWindowScene, let appDelegate = appDelegate, let factory = appDelegate.reactNativeFactory else { return }',
  '    let window = UIWindow(windowScene: windowScene)',
  '    self.window = window',
  '    appDelegate.window = window',
  '    var launchOptions: [UIApplication.LaunchOptionsKey: Any] = appDelegate.launchOptionsForScene ?? [:]',
  '    if let url = connectionOptions.urlContexts.first?.url { launchOptions[.url] = url }',
  '    if let metadata = connectionOptions.cloudKitShareMetadata { SceneDelegate.recordShare(metadata) }',
  '    factory.startReactNative(withModuleName: "main", in: window, launchOptions: launchOptions.isEmpty ? nil : launchOptions)',
  '    for activity in connectionOptions.userActivities {',
  '      _ = appDelegate.application(UIApplication.shared, continue: activity, restorationHandler: { _ in })',
  '    }',
  '  }',
  '',
  '  // Links: handed to the AppDelegate methods so Expo\'s linking still sees them.',
  '  func scene(_ scene: UIScene, openURLContexts URLContexts: Set<UIOpenURLContext>) {',
  '    guard let appDelegate = appDelegate else { return }',
  '    for context in URLContexts { _ = appDelegate.application(UIApplication.shared, open: context.url, options: [:]) }',
  '  }',
  '',
  '  func scene(_ scene: UIScene, continue userActivity: NSUserActivity) {',
  '    _ = appDelegate?.application(UIApplication.shared, continue: userActivity, restorationHandler: { _ in })',
  '  }',
  '',
  '  // A tapped CloudKit share link, with the app already running. Same as the AppDelegate method above, which iOS no longer calls under scenes.',
  '  func windowScene(_ windowScene: UIWindowScene, userDidAcceptCloudKitShareWith metadata: CKShare.Metadata) {',
  '    SceneDelegate.recordShare(metadata)',
  '  }',
  '',
  '  static func recordShare(_ metadata: CKShare.Metadata) {',
  '    if let url = metadata.share.url?.absoluteString {',
  `      UserDefaults.standard.set(url, forKey: "${PENDING_INVITE_KEY}")`,
  '    }',
  `    NotificationCenter.default.post(name: Notification.Name("${SHARE_NOTIFICATION}"), object: metadata)`,
  '  }',
  '}',
  '',
].join('\n');

function injectSceneLifecycle(contents, language = 'swift') {
  if (language !== 'swift') throw new Error('withCloudKit: the scene lifecycle is only written into a Swift AppDelegate.');
  if (contents.includes(SCENE_MARKER)) return contents;
  const startBlock = /^[ \t]*#if os\(iOS\) \|\| os\(tvOS\)\r?\n[ \t]*window = UIWindow\(frame: UIScreen\.main\.bounds\)[\s\S]*?startReactNative\([\s\S]*?\)\r?\n[ \t]*#endif[ \t]*\r?\n/m;
  const property = /^([ \t]*)var reactNativeFactory: RCTReactNativeFactory\?[ \t]*\r?\n/m;
  if (!startBlock.test(contents) || !property.test(contents)) {
    throw new Error('withCloudKit: the generated AppDelegate.swift does not look like the Expo SDK 54 template (no window and startReactNative block, or no reactNativeFactory property), so the scene lifecycle was not added. Without it the app stops at launch on iOS 27. See plugins/withCloudKit.js.');
  }
  let out = contents.replace(startBlock, '    // The window is made in SceneDelegate now. The launch options wait here until it starts React Native.\n    launchOptionsForScene = launchOptions\n');
  out = out.replace(property, (m, pad) => `${m}${pad}var launchOptionsForScene: [UIApplication.LaunchOptionsKey: Any]?\n`);
  if (!/^\s*import CloudKit\s*$/m.test(out)) out = out.replace(/^(\s*import [^\n]+\n)/m, '$1import CloudKit\n');
  return out.replace(/\s*$/, '\n') + SCENE_DELEGATE;
}

const withSceneManifest = (config) =>
  withInfoPlist(config, (c) => {
    applySceneManifest(c.modResults);
    return c;
  });

const withSceneDelegate = (config) =>
  withAppDelegate(config, (c) => {
    c.modResults.contents = injectSceneLifecycle(c.modResults.contents, c.modResults.language);
    return c;
  });

const withShareLinkHandler = (config) =>
  withAppDelegate(config, (c) => {
    c.modResults.contents = injectShareLinkHandler(c.modResults.contents, c.modResults.language);
    return c;
  });

module.exports = (config) =>
  withSceneManifest(withSceneDelegate(withPodsTarget(withShareLinkHandler(withProjectTarget(withPodfileTarget(withSharingSupport(withIcloudEntitlements(config))))))));
module.exports.injectShareLinkHandler = injectShareLinkHandler;
module.exports.injectPodsTarget = injectPodsTarget;
module.exports.injectSceneLifecycle = injectSceneLifecycle;
module.exports.applySceneManifest = applySceneManifest;
module.exports.applyEntitlements = applyEntitlements;
